<script setup>
import{computed,onMounted,ref}from'vue';import{api}from'../api.js';import{apiErrorMessage}from'../stores/notifications.js';import{formatDateTime,formatGold}from'../utils/format.js';import AdminNav from'../components/AdminNav.vue';import SkeletonRows from'../components/SkeletonRows.vue'
const data=ref(null),loading=ref(true),error=ref('');const sql=computed(()=>`UPDATE treasury_token_settings SET token_unit_value = ${data.value?.economy?.token_unit_value??0}, updated_at = NOW() WHERE id = 1;`)
async function load(){loading.value=true;error.value='';try{data.value=(await api.get('/api/admin/settings')).data}catch(e){error.value=apiErrorMessage(e,'Не удалось загрузить настройки.')}finally{loading.value=false}}onMounted(load)
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">АДМИНКА</p><h1>Настройки экономики</h1><p class="muted">Контроль параметров, влияющих на отображение казны</p></div><button :disabled="loading" @click="load">Обновить</button></div><AdminNav/><p v-if="error" class="notice error">{{ error }}</p><SkeletonRows v-if="loading" :rows="3"/><template v-else-if="data"><div class="settings-grid"><article class="panel"><span>Стоимость жетона</span><strong>{{ formatGold(data.economy.token_unit_value) }}</strong><small>Изменено: {{ formatDateTime(data.economy.token_updated_at) }}</small></article><article class="panel"><span>Формула отображения</span><strong>⌊ золото ÷ стоимость жетона ⌋</strong><small>Количество жетонов вычисляется автоматически</small></article></div><div class="panel settings-instruction"><h2>Изменение стоимости</h2><p>Параметр по-прежнему изменяется вручную в PostgreSQL. Сначала замените число в запросе, затем обновите эту страницу.</p><code>{{ sql }}</code><div class="notice warning">Изменение цены не двигает золото и не создаёт финансовую транзакцию — меняется только эквивалент в жетонах.</div></div></template></section></template>
